// CSD_RATIONALE_BEGIN
// This strategy follows a pattern where we start with unconstrained generation to explore possible solutions.
// Once we encounter "<<", we enter a constrained mode where we strictly adhere to grammar rules until encountering ">>".
// In constrained mode, we use a combination of constrained steps and soft constrained steps to ensure we stay within valid grammar boundaries.
// We also use the ConfidenceGatedStep to avoid getting stuck in invalid states and exit the constrained mode when necessary.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if next == "<<" {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      steps := steps + 1;
      if wasConstrained {
        currentConstrained := currentConstrained + [next];
        if next == ">>" { insideConstrained := false; }
      } else {
        insideConstrained := false;
      }
    }
  }
}
cost := helpers.cost;

